  constructor(message, line) {
    super(message)
    this.line = line
  }
}

const NAME_RE = /^[A-Za-z0-9_-]+$/
const COUNT_RE = /^[1-9][0-9]*$/

/**
 * Split raw input into trimmed, non-empty, non-comment lines, each tagged
 * with its 1-based line number in the original input.
 */
function splitLines(input) {
  const rawLines = input.split('\n')
  if (rawLines.length > 0 && rawLines[rawLines.length - 1] === '') {
    rawLines.pop()
  }
  const lines = []
  for (let i = 0; i < rawLines.length; i++) {
    const trimmed = rawLines[i].trim()
    if (trimmed === '' || trimmed.startsWith('#')) continue
    lines.push({ line: i + 1, tokens: trimmed.split(/\s+/) })
  }
  return lines
}

export function parseElection(input) {
  const lines = splitLines(input)

  let candidates = null
  const candidateSet = new Set()
  const ballots = []

  for (const { line, tokens } of lines) {
    const directive = tokens[0]

    if (directive === 'candidates') {
      if (candidates !== null) {
        throw new ParseError('candidates must be declared once, before any ballot', line)
      }
      if (tokens.length < 2) {
        throw new ParseError('expected candidates <name>...', line)
      }
      candidates = []
      for (const name of tokens.slice(1)) {
        if (!NAME_RE.test(name)) {
          throw new ParseError(`invalid candidate name ${name}`, line)
        }
        if (candidateSet.has(name)) {
          throw new ParseError(`candidate ${name} is declared twice`, line)
        }
        candidateSet.add(name)
        candidates.push(name)
      }
    } else if (directive === 'ballot') {
      if (candidates === null) {
        throw new ParseError('candidates must be declared once, before any ballot', line)
      }
      if (tokens.length < 3) {
        throw new ParseError('expected ballot <count> <candidate>...', line)
      }
      const countStr = tokens[1]
      if (!COUNT_RE.test(countStr)) {
        throw new ParseError('count must be a positive integer', line)
      }
      const count = Number(countStr)
      const names = tokens.slice(2)
      const seen = new Set()
      for (const name of names) {
        if (!candidateSet.has(name)) {
          throw new ParseError(`unknown candidate ${name}`, line)
        }
        if (seen.has(name)) {
          throw new ParseError(`candidate ${name} is repeated`, line)
        }
        seen.add(name)
      }
      ballots.push({ count, names })
    } else {
      throw new ParseError(`unknown directive ${directive}`, line)
    }
  }

  if (candidates === null) {
    throw new ParseError('no candidates')
  }

  return { candidates, ballots }
}
"}

