{"file_path":"./src/election.js","content":"/**
 * Runs an instant-runoff count over a parsed election and yields the results
 * of each round, plus the eventual winner (or the lack of one).
 */

/**
 * Break a tie among the candidates in `tied`, all with the fewest votes in
 * the just-counted round, using the vote history recorded so far (one entry
 * per round counted, mapping each candidate continuing that round to its
 * vote count). Returns the name of the candidate to eliminate.
 */
function breakTie(tied, history) {
  let candidates = tied.slice()
  while (candidates.length > 1) {
    let separated = false
    for (const roundVotes of history) {
      const values = candidates.map((c) => roundVotes.get(c))
      const allEqual = values.every((v) => v === values[0])
      if (!allEqual) {
        const min = Math.min(...values)
        candidates = candidates.filter((c) => roundVotes.get(c) === min)
        separated = true
        break
      }
    }
    if (!separated) break
  }
  if (candidates.length === 1) return candidates[0]
  return candidates.reduce((a, b) => (a > b ? a : b))
}

/**
 * Count the election. Returns an array of round summaries
 * `{ counts: Map<name, votes>, exhausted, eliminated }` (eliminated is null
 * for the final round) and the winner's name, or null if there is none.
 */
export function runElection(election) {
  const { candidates, ballots } = election
  let continuing = new Set(candidates)
  const history = []
  const rounds = []
  let winner = null

  for (;;) {
    const counts = new Map()
    for (const name of continuing) counts.set(name, 0)
    let exhausted = 0

    for (const ballot of ballots) {
      const choice = ballot.names.find((name) => continuing.has(name))
      if (choice === undefined) {
        exhausted += ballot.count
      } else {
        counts.set(choice, counts.get(choice) + ballot.count)
      }
    }

    history.push(counts)

    const activeTotal = [...counts.values()].reduce((a, b) => a + b, 0)

    let eliminated = null

    if (activeTotal === 0) {
      rounds.push({ counts, exhausted, eliminated })
      winner = null
      break
    }

    let majorityWinner = null
    for (const [name, votes] of counts) {
      if (votes * 2 > activeTotal) {
        majorityWinner = name
        break
      }
    }

    if (majorityWinner !== null) {
      rounds.push({ counts, exhausted, eliminated })
      winner = majorityWinner
      break
    }

    const min = Math.min(...counts.values())
    const tied = [...counts.keys()].filter((name) => counts.get(name) === min)
    eliminated = tied.length === 1 ? tied[0] : breakTie(tied, history)

    rounds.push({ counts, exhausted, eliminated })
    continuing.delete(eliminated)
  }

  return { rounds, winner }
}
"}

